import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    count = 0
    for l in range(n):
        for r in range(l, n):
            if sum(a[l:r + 1]) <= s:
                count += 1
    print(count)


main()
